import React, { useCallback, useEffect, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import {
  Alert,
  Button,
  Card,
  CardContent,
  Chip,
  Dialog,
  DialogActions,
  DialogContent,
  DialogTitle,
  FormControl,
  Grid,
  IconButton,
  InputLabel,
  MenuItem,
  Paper,
  Select,
  Tab,
  Tabs,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TablePagination,
  TableRow,
  TextField,
  Typography,
  Stack,
} from '@mui/material';
import { Search, Visibility } from '@mui/icons-material';
import axios from 'axios';
import SupportPortalLayout from './SupportPortalLayout';
import { buildApiUrl } from '../../config/apiConfig';

interface Statistics {
  msme: {
    total: number;
    pending: number;
    verified: number;
    flagged: number;
    suspended: number;
  };
  tickets: {
    open: number;
    inProgress: number;
  };
  privacyRequests: {
    pending: number;
  };
}

interface MSMEItem {
  _id: string;
  companyName: string;
  industry: string;
  status: string;
  contact: { email: string; phone: string };
  createdAt: string;
  userId: { email: string; lastLogin?: string; isActive?: boolean };
  usageSummary: {
    planTier: string;
    billingStatus: string;
    paidUntil: string | null;
  };
  openTicketCount: number;
  pendingPrivacyRequests: number;
}

interface SupportTicket {
  _id: string;
  subject: string;
  description: string;
  category: string;
  status: string;
  priority: string;
  solution: string;
  createdAt: string;
  msmeId: { _id: string; companyName: string; status: string };
}

interface CapaRecord {
  _id: string;
  capaNumber: string;
  title: string;
  description: string;
  severity: string;
  status: string;
  rootCause: string;
  correctiveAction: string;
  supportTicketId?: { _id: string; subject: string; status: string } | null;
  createdAt: string;
}

interface PrivacyRequest {
  _id: string;
  type: string;
  status: string;
  description: string;
  response: string;
  createdAt: string;
  userId: { email: string; profile?: { firstName?: string; lastName?: string } };
  msme?: { companyName: string; status: string } | null;
}

const STATUS_COLORS: Record<string, 'default' | 'success' | 'warning' | 'error' | 'info'> = {
  pending: 'warning',
  verified: 'success',
  flagged: 'error',
  suspended: 'default',
  open: 'error',
  in_progress: 'info',
  waiting_on_customer: 'warning',
  resolved: 'success',
  closed: 'default',
};

const authHeaders = () => ({ Authorization: `Bearer ${localStorage.getItem('token')}` });

const SupportDashboard: React.FC = () => {
  const navigate = useNavigate();
  const [tab, setTab] = useState(0);
  const [statistics, setStatistics] = useState<Statistics | null>(null);
  const [msmes, setMsmes] = useState<MSMEItem[]>([]);
  const [tickets, setTickets] = useState<SupportTicket[]>([]);
  const [privacyRequests, setPrivacyRequests] = useState<PrivacyRequest[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [searchTerm, setSearchTerm] = useState('');
  const [statusFilter, setStatusFilter] = useState('');
  const [page, setPage] = useState(0);
  const [rowsPerPage, setRowsPerPage] = useState(20);
  const [total, setTotal] = useState(0);
  const [ticketDialog, setTicketDialog] = useState<{ open: boolean; msmeId: string; companyName: string }>({
    open: false,
    msmeId: '',
    companyName: '',
  });
  const [ticketForm, setTicketForm] = useState({
    subject: '',
    description: '',
    category: 'other',
    priority: 'medium',
  });
  const [creatingTicket, setCreatingTicket] = useState(false);
  const [resolveDialog, setResolveDialog] = useState<{ open: boolean; ticket: SupportTicket | null }>({
    open: false,
    ticket: null,
  });
  const [solutionText, setSolutionText] = useState('');
  const [privacyDialog, setPrivacyDialog] = useState<{ open: boolean; request: PrivacyRequest | null }>({
    open: false,
    request: null,
  });
  const [privacyResponse, setPrivacyResponse] = useState('');
  const [ticketStatusFilter, setTicketStatusFilter] = useState('');
  const [ticketCategoryFilter, setTicketCategoryFilter] = useState('');
  const [suggestingSolution, setSuggestingSolution] = useState(false);
  const [aiConfidence, setAiConfidence] = useState<number | null>(null);
  const [capaRecords, setCapaRecords] = useState<CapaRecord[]>([]);
  const [capaDialog, setCapaDialog] = useState<{ open: boolean; ticket: SupportTicket | null }>({
    open: false,
    ticket: null,
  });
  const [capaForm, setCapaForm] = useState({ title: '', description: '', severity: 'minor' });
  const [creatingCapa, setCreatingCapa] = useState(false);
  const [openCapaAfterResolve, setOpenCapaAfterResolve] = useState(false);

  const fetchStatistics = useCallback(async () => {
    const response = await axios.get(buildApiUrl('/support/statistics'), { headers: authHeaders() });
    setStatistics(response.data.data);
  }, []);

  const fetchMSMEs = useCallback(async () => {
    setLoading(true);
    try {
      const response = await axios.get(buildApiUrl('/support/msme/list'), {
        params: {
          page: page + 1,
          limit: rowsPerPage,
          search: searchTerm || undefined,
          status: statusFilter || undefined,
        },
        headers: authHeaders(),
      });
      setMsmes(response.data.data.msmes);
      setTotal(response.data.data.pagination.total);
    } catch (fetchError: unknown) {
      const status = (fetchError as { response?: { status?: number } })?.response?.status;
      if (status === 401 || status === 403) {
        navigate('/login');
      } else {
        setError('Failed to load MSME accounts');
      }
    } finally {
      setLoading(false);
    }
  }, [navigate, page, rowsPerPage, searchTerm, statusFilter]);

  const fetchTickets = useCallback(async () => {
    const response = await axios.get(buildApiUrl('/support/tickets'), {
      params: {
        limit: 50,
        ...(ticketStatusFilter ? { status: ticketStatusFilter } : {}),
        ...(ticketCategoryFilter ? { category: ticketCategoryFilter } : {}),
      },
      headers: authHeaders(),
    });
    setTickets(response.data.data.tickets);
  }, [ticketStatusFilter, ticketCategoryFilter]);

  const fetchPrivacyRequests = useCallback(async () => {
    const response = await axios.get(buildApiUrl('/support/privacy-requests'), {
      params: { limit: 50 },
      headers: authHeaders(),
    });
    setPrivacyRequests(response.data.data.requests);
  }, []);

  const fetchCapaRecords = useCallback(async () => {
    const response = await axios.get(buildApiUrl('/quality/capa'), {
      params: { limit: 50 },
      headers: authHeaders(),
    });
    setCapaRecords(response.data.data.records);
  }, []);

  useEffect(() => {
    const load = async () => {
      try {
        await Promise.all([fetchStatistics(), fetchMSMEs(), fetchTickets(), fetchPrivacyRequests(), fetchCapaRecords()]);
      } catch {
        setError('Failed to load support dashboard');
      }
    };
    load();
  }, [fetchStatistics, fetchMSMEs, fetchTickets, fetchPrivacyRequests, fetchCapaRecords]);

  const handleCreateTicket = async () => {
    if (!ticketForm.subject.trim() || !ticketForm.description.trim()) return;
    setCreatingTicket(true);
    try {
      await axios.post(
        buildApiUrl('/support/tickets'),
        { msmeId: ticketDialog.msmeId, ...ticketForm },
        { headers: authHeaders() }
      );
      setTicketDialog({ open: false, msmeId: '', companyName: '' });
      setTicketForm({ subject: '', description: '', category: 'other', priority: 'medium' });
      await Promise.all([fetchTickets(), fetchStatistics(), fetchMSMEs()]);
    } catch {
      setError('Failed to create support ticket');
    } finally {
      setCreatingTicket(false);
    }
  };

  const handleSuggestSolution = async () => {
    if (!resolveDialog.ticket) return;
    setSuggestingSolution(true);
    setAiConfidence(null);
    try {
      const response = await axios.post(
        buildApiUrl('/support/ai-assist'),
        {
          query: resolveDialog.ticket.description,
          subject: resolveDialog.ticket.subject,
          ticketId: resolveDialog.ticket._id,
          msmeId: resolveDialog.ticket.msmeId?._id,
        },
        { headers: authHeaders() }
      );
      const advisory = response.data.data;
      if (advisory?.answer) {
        setSolutionText(advisory.answer);
        setAiConfidence(advisory.confidence ?? null);
      }
    } catch {
      setError('AI suggestion failed — enter a manual solution.');
    } finally {
      setSuggestingSolution(false);
    }
  };

  const handleResolveTicket = async (status: 'resolved' | 'closed') => {
    if (!resolveDialog.ticket) return;
    try {
      await axios.patch(
        buildApiUrl(`/support/tickets/${resolveDialog.ticket._id}`),
        { status, solution: solutionText },
        { headers: authHeaders() }
      );
      const resolvedTicket = resolveDialog.ticket;
      setResolveDialog({ open: false, ticket: null });
      setSolutionText('');
      setAiConfidence(null);
      await Promise.all([fetchTickets(), fetchStatistics()]);
      if (openCapaAfterResolve) {
        setOpenCapaAfterResolve(false);
        setCapaForm({
          title: resolvedTicket.subject,
          description: resolvedTicket.description,
          severity: 'minor',
        });
        setCapaDialog({ open: true, ticket: resolvedTicket });
      }
    } catch {
      setError('Failed to update ticket');
    }
  };

  const handleCreateCapa = async () => {
    if (!capaForm.title.trim() || !capaForm.description.trim()) return;
    setCreatingCapa(true);
    try {
      await axios.post(
        buildApiUrl('/quality/capa'),
        {
          ...capaForm,
          supportTicketId: capaDialog.ticket?._id,
          source: capaDialog.ticket ? 'support_ticket' : 'other',
        },
        { headers: authHeaders() }
      );
      setCapaDialog({ open: false, ticket: null });
      setCapaForm({ title: '', description: '', severity: 'minor' });
      await fetchCapaRecords();
    } catch {
      setError('Failed to create CAPA record');
    } finally {
      setCreatingCapa(false);
    }
  };

  const handlePrivacyUpdate = async (status: 'completed' | 'rejected' | 'in_progress') => {
    if (!privacyDialog.request) return;
    try {
      await axios.patch(
        buildApiUrl(`/support/privacy-requests/${privacyDialog.request._id}`),
        { status, response: privacyResponse },
        { headers: authHeaders() }
      );
      setPrivacyDialog({ open: false, request: null });
      setPrivacyResponse('');
      await Promise.all([fetchPrivacyRequests(), fetchStatistics()]);
    } catch {
      setError('Failed to update privacy request');
    }
  };

  return (
    <SupportPortalLayout
      title="Customer Support Dashboard"
      subtitle="Monitor MSME account status, usage, issues, and resolutions"
    >
      {error && (
        <Alert severity="error" sx={{ mb: 2 }} onClose={() => setError(null)}>
          {error}
        </Alert>
      )}

      {statistics && (
        <Grid container spacing={2} sx={{ mb: 3 }}>
          {[
            { label: 'Total MSMEs', value: statistics.msme.total, color: 'primary.main' },
            { label: 'Pending Verification', value: statistics.msme.pending, color: 'warning.main' },
            { label: 'Open Tickets', value: statistics.tickets.open, color: 'error.main' },
            { label: 'Privacy Requests', value: statistics.privacyRequests.pending, color: 'info.main' },
          ].map((stat) => (
            <Grid item xs={12} sm={6} md={3} key={stat.label}>
              <Card>
                <CardContent>
                  <Typography variant="body2" color="text.secondary">{stat.label}</Typography>
                  <Typography variant="h4" sx={{ fontWeight: 700, color: stat.color }}>
                    {stat.value}
                  </Typography>
                </CardContent>
              </Card>
            </Grid>
          ))}
        </Grid>
      )}

      <Paper sx={{ mb: 3 }}>
        <Tabs value={tab} onChange={(_, value) => setTab(value)}>
          <Tab label="MSME Accounts" />
          <Tab label={`Support Tickets (${tickets.length})`} />
          <Tab label={`Privacy Requests (${privacyRequests.length})`} />
          <Tab label={`CAPA (${capaRecords.length})`} />
        </Tabs>
      </Paper>

      {tab === 0 && (
        <>
          <Paper sx={{ p: 2, mb: 2 }}>
            <Grid container spacing={2} alignItems="center">
              <Grid item xs={12} md={6}>
                <TextField
                  fullWidth
                  size="small"
                  label="Search by company, email, GST, PAN"
                  value={searchTerm}
                  onChange={(e) => { setSearchTerm(e.target.value); setPage(0); }}
                  onKeyDown={(e) => { if (e.key === 'Enter') fetchMSMEs(); }}
                  InputProps={{
                    endAdornment: (
                      <IconButton onClick={() => fetchMSMEs()} size="small" aria-label="Search">
                        <Search />
                      </IconButton>
                    ),
                  }}
                />
              </Grid>
              <Grid item xs={12} md={3}>
                <FormControl fullWidth size="small">
                  <InputLabel>Status</InputLabel>
                  <Select
                    value={statusFilter}
                    label="Status"
                    onChange={(e) => { setStatusFilter(e.target.value); setPage(0); }}
                  >
                    <MenuItem value="">All</MenuItem>
                    <MenuItem value="pending">Pending</MenuItem>
                    <MenuItem value="verified">Verified</MenuItem>
                    <MenuItem value="flagged">Flagged</MenuItem>
                    <MenuItem value="suspended">Suspended</MenuItem>
                  </Select>
                </FormControl>
              </Grid>
            </Grid>
          </Paper>

          <TableContainer component={Paper}>
            <Table size="small">
              <TableHead>
                <TableRow>
                  <TableCell><strong>Company</strong></TableCell>
                  <TableCell><strong>Status</strong></TableCell>
                  <TableCell><strong>Plan / Billing</strong></TableCell>
                  <TableCell><strong>Open Issues</strong></TableCell>
                  <TableCell><strong>Last Login</strong></TableCell>
                  <TableCell><strong>Actions</strong></TableCell>
                </TableRow>
              </TableHead>
              <TableBody>
                {loading ? (
                  <TableRow>
                    <TableCell colSpan={6} align="center">Loading accounts...</TableCell>
                  </TableRow>
                ) : msmes.length === 0 ? (
                  <TableRow>
                    <TableCell colSpan={6} align="center">No MSME accounts found</TableCell>
                  </TableRow>
                ) : (
                  msmes.map((msme) => (
                    <TableRow key={msme._id} hover>
                      <TableCell>
                        <Typography variant="body2" sx={{ fontWeight: 600 }}>{msme.companyName}</Typography>
                        <Typography variant="caption" color="text.secondary">{msme.userId?.email}</Typography>
                      </TableCell>
                      <TableCell>
                        <Chip
                          label={msme.status}
                          size="small"
                          color={STATUS_COLORS[msme.status] || 'default'}
                        />
                      </TableCell>
                      <TableCell>
                        <Typography variant="body2">{msme.usageSummary?.planTier || 'free'}</Typography>
                        <Typography variant="caption" color="text.secondary">
                          {msme.usageSummary?.billingStatus || 'none'}
                        </Typography>
                      </TableCell>
                      <TableCell>
                        {msme.openTicketCount > 0 && (
                          <Chip label={`${msme.openTicketCount} ticket(s)`} size="small" color="error" sx={{ mr: 0.5 }} />
                        )}
                        {msme.pendingPrivacyRequests > 0 && (
                          <Chip label={`${msme.pendingPrivacyRequests} privacy`} size="small" color="info" />
                        )}
                        {msme.openTicketCount === 0 && msme.pendingPrivacyRequests === 0 && '—'}
                      </TableCell>
                      <TableCell>
                        {msme.userId?.lastLogin
                          ? new Date(msme.userId.lastLogin).toLocaleDateString()
                          : 'Never'}
                      </TableCell>
                      <TableCell>
                        <Button
                          size="small"
                          startIcon={<Visibility />}
                          onClick={() => navigate(`/support/msme/${msme._id}`)}
                        >
                          View
                        </Button>
                        <Button
                          size="small"
                          onClick={() => setTicketDialog({ open: true, msmeId: msme._id, companyName: msme.companyName })}
                        >
                          New Ticket
                        </Button>
                      </TableCell>
                    </TableRow>
                  ))
                )}
              </TableBody>
            </Table>
            <TablePagination
              component="div"
              count={total}
              page={page}
              onPageChange={(_, newPage) => setPage(newPage)}
              rowsPerPage={rowsPerPage}
              onRowsPerPageChange={(e) => { setRowsPerPage(parseInt(e.target.value, 10)); setPage(0); }}
            />
          </TableContainer>
        </>
      )}

      {tab === 1 && (
        <>
          <Stack direction="row" spacing={2} sx={{ mb: 2 }} flexWrap="wrap" useFlexGap>
            <FormControl size="small" sx={{ minWidth: 140 }}>
              <InputLabel>Status</InputLabel>
              <Select
                label="Status"
                value={ticketStatusFilter}
                onChange={(e) => setTicketStatusFilter(e.target.value)}
              >
                <MenuItem value="">All</MenuItem>
                <MenuItem value="open">Open</MenuItem>
                <MenuItem value="in_progress">In progress</MenuItem>
                <MenuItem value="resolved">Resolved</MenuItem>
                <MenuItem value="closed">Closed</MenuItem>
              </Select>
            </FormControl>
            <FormControl size="small" sx={{ minWidth: 160 }}>
              <InputLabel>Category</InputLabel>
              <Select
                label="Category"
                value={ticketCategoryFilter}
                onChange={(e) => setTicketCategoryFilter(e.target.value)}
              >
                <MenuItem value="">All</MenuItem>
                <MenuItem value="account_access">Account access</MenuItem>
                <MenuItem value="billing">Billing</MenuItem>
                <MenuItem value="data_privacy">Data privacy</MenuItem>
                <MenuItem value="technical">Technical</MenuItem>
                <MenuItem value="onboarding">Onboarding</MenuItem>
                <MenuItem value="other">Other</MenuItem>
              </Select>
            </FormControl>
            <Button variant="outlined" size="small" onClick={() => fetchTickets()}>Apply filters</Button>
          </Stack>
        <TableContainer component={Paper}>
          <Table size="small">
            <TableHead>
              <TableRow>
                <TableCell><strong>Subject</strong></TableCell>
                <TableCell><strong>Company</strong></TableCell>
                <TableCell><strong>Category</strong></TableCell>
                <TableCell><strong>Priority</strong></TableCell>
                <TableCell><strong>Status</strong></TableCell>
                <TableCell><strong>Created</strong></TableCell>
                <TableCell><strong>Actions</strong></TableCell>
              </TableRow>
            </TableHead>
            <TableBody>
              {tickets.length === 0 ? (
                <TableRow>
                  <TableCell colSpan={7} align="center">No support tickets</TableCell>
                </TableRow>
              ) : (
                tickets.map((ticket) => (
                  <TableRow key={ticket._id} hover>
                    <TableCell>{ticket.subject}</TableCell>
                    <TableCell>
                      {ticket.msmeId?._id ? (
                        <Button size="small" onClick={() => navigate(`/support/msme/${ticket.msmeId._id}`)}>
                          {ticket.msmeId?.companyName || 'View MSME'}
                        </Button>
                      ) : (
                        ticket.msmeId?.companyName || 'N/A'
                      )}
                    </TableCell>
                    <TableCell>{ticket.category}</TableCell>
                    <TableCell>{ticket.priority}</TableCell>
                    <TableCell>
                      <Chip label={ticket.status} size="small" color={STATUS_COLORS[ticket.status] || 'default'} />
                    </TableCell>
                    <TableCell>{new Date(ticket.createdAt).toLocaleDateString()}</TableCell>
                    <TableCell>
                      {ticket.status !== 'resolved' && ticket.status !== 'closed' && (
                        <Button
                          size="small"
                          onClick={() => {
                            setResolveDialog({ open: true, ticket });
                            setSolutionText(ticket.solution || '');
                          }}
                        >
                          Resolve
                        </Button>
                      )}
                      {ticket.solution && (
                        <Typography variant="caption" display="block" color="text.secondary">
                          Solution recorded
                        </Typography>
                      )}
                    </TableCell>
                  </TableRow>
                ))
              )}
            </TableBody>
          </Table>
        </TableContainer>
        </>
      )}

      {tab === 2 && (
        <TableContainer component={Paper}>
          <Table size="small">
            <TableHead>
              <TableRow>
                <TableCell><strong>Type</strong></TableCell>
                <TableCell><strong>User / Company</strong></TableCell>
                <TableCell><strong>Description</strong></TableCell>
                <TableCell><strong>Status</strong></TableCell>
                <TableCell><strong>Created</strong></TableCell>
                <TableCell><strong>Actions</strong></TableCell>
              </TableRow>
            </TableHead>
            <TableBody>
              {privacyRequests.length === 0 ? (
                <TableRow>
                  <TableCell colSpan={6} align="center">No privacy requests</TableCell>
                </TableRow>
              ) : (
                privacyRequests.map((request) => (
                  <TableRow key={request._id} hover>
                    <TableCell>{request.type}</TableCell>
                    <TableCell>
                      <Typography variant="body2">{request.userId?.email}</Typography>
                      <Typography variant="caption" color="text.secondary">
                        {request.msme?.companyName || 'N/A'}
                      </Typography>
                    </TableCell>
                    <TableCell>{request.description.slice(0, 80)}{request.description.length > 80 ? '…' : ''}</TableCell>
                    <TableCell>
                      <Chip label={request.status} size="small" color={STATUS_COLORS[request.status] || 'default'} />
                    </TableCell>
                    <TableCell>{new Date(request.createdAt).toLocaleDateString()}</TableCell>
                    <TableCell>
                      {request.status !== 'completed' && request.status !== 'rejected' && (
                        <Button
                          size="small"
                          onClick={() => {
                            setPrivacyDialog({ open: true, request });
                            setPrivacyResponse(request.response || '');
                          }}
                        >
                          Respond
                        </Button>
                      )}
                    </TableCell>
                  </TableRow>
                ))
              )}
            </TableBody>
          </Table>
        </TableContainer>
      )}

      {tab === 3 && (
        <>
          <Stack direction="row" spacing={2} sx={{ mb: 2 }}>
            <Button
              variant="contained"
              size="small"
              onClick={() => {
                setCapaForm({ title: '', description: '', severity: 'minor' });
                setCapaDialog({ open: true, ticket: null });
              }}
            >
              New CAPA
            </Button>
            <Button variant="outlined" size="small" onClick={() => fetchCapaRecords()}>Refresh</Button>
          </Stack>
          <TableContainer component={Paper}>
            <Table size="small">
              <TableHead>
                <TableRow>
                  <TableCell><strong>CAPA #</strong></TableCell>
                  <TableCell><strong>Title</strong></TableCell>
                  <TableCell><strong>Severity</strong></TableCell>
                  <TableCell><strong>Status</strong></TableCell>
                  <TableCell><strong>Linked ticket</strong></TableCell>
                  <TableCell><strong>Created</strong></TableCell>
                </TableRow>
              </TableHead>
              <TableBody>
                {capaRecords.length === 0 ? (
                  <TableRow>
                    <TableCell colSpan={6} align="center">No CAPA records</TableCell>
                  </TableRow>
                ) : (
                  capaRecords.map((record) => (
                    <TableRow key={record._id} hover>
                      <TableCell>{record.capaNumber}</TableCell>
                      <TableCell>{record.title}</TableCell>
                      <TableCell>{record.severity}</TableCell>
                      <TableCell>
                        <Chip label={record.status} size="small" color={record.status === 'closed' ? 'default' : 'warning'} />
                      </TableCell>
                      <TableCell>{record.supportTicketId?.subject || '—'}</TableCell>
                      <TableCell>{new Date(record.createdAt).toLocaleDateString()}</TableCell>
                    </TableRow>
                  ))
                )}
              </TableBody>
            </Table>
          </TableContainer>
        </>
      )}

      <Dialog open={ticketDialog.open} onClose={() => setTicketDialog({ open: false, msmeId: '', companyName: '' })} maxWidth="sm" fullWidth>
        <DialogTitle>New Support Ticket — {ticketDialog.companyName}</DialogTitle>
        <DialogContent>
          <TextField
            fullWidth
            margin="dense"
            label="Subject"
            value={ticketForm.subject}
            onChange={(e) => setTicketForm((prev) => ({ ...prev, subject: e.target.value }))}
            required
          />
          <TextField
            fullWidth
            margin="dense"
            label="Description"
            value={ticketForm.description}
            onChange={(e) => setTicketForm((prev) => ({ ...prev, description: e.target.value }))}
            multiline
            minRows={3}
            required
          />
          <FormControl fullWidth margin="dense" size="small">
            <InputLabel>Category</InputLabel>
            <Select
              value={ticketForm.category}
              label="Category"
              onChange={(e) => setTicketForm((prev) => ({ ...prev, category: e.target.value }))}
            >
              <MenuItem value="account_access">Account Access</MenuItem>
              <MenuItem value="billing">Billing</MenuItem>
              <MenuItem value="data_privacy">Data Privacy</MenuItem>
              <MenuItem value="technical">Technical</MenuItem>
              <MenuItem value="onboarding">Onboarding</MenuItem>
              <MenuItem value="other">Other</MenuItem>
            </Select>
          </FormControl>
          <FormControl fullWidth margin="dense" size="small">
            <InputLabel>Priority</InputLabel>
            <Select
              value={ticketForm.priority}
              label="Priority"
              onChange={(e) => setTicketForm((prev) => ({ ...prev, priority: e.target.value }))}
            >
              <MenuItem value="low">Low</MenuItem>
              <MenuItem value="medium">Medium</MenuItem>
              <MenuItem value="high">High</MenuItem>
              <MenuItem value="urgent">Urgent</MenuItem>
            </Select>
          </FormControl>
        </DialogContent>
        <DialogActions>
          <Button onClick={() => setTicketDialog({ open: false, msmeId: '', companyName: '' })}>Cancel</Button>
          <Button variant="contained" onClick={handleCreateTicket} disabled={creatingTicket}>
            {creatingTicket ? 'Creating...' : 'Create Ticket'}
          </Button>
        </DialogActions>
      </Dialog>

      <Dialog open={resolveDialog.open} onClose={() => setResolveDialog({ open: false, ticket: null })} maxWidth="sm" fullWidth>
        <DialogTitle>Resolve Ticket — {resolveDialog.ticket?.subject}</DialogTitle>
        <DialogContent>
          <Typography variant="body2" color="text.secondary" sx={{ mb: 2 }}>
            {resolveDialog.ticket?.description}
          </Typography>
          <Stack direction="row" spacing={1} sx={{ mb: 1 }} alignItems="center">
            <Button
              size="small"
              variant="outlined"
              onClick={handleSuggestSolution}
              disabled={suggestingSolution}
            >
              {suggestingSolution ? 'Generating…' : 'AI suggest solution'}
            </Button>
            {aiConfidence !== null && (
              <Chip
                size="small"
                label={`Confidence ${Math.round(aiConfidence * 100)}%`}
                color={aiConfidence >= 0.55 ? 'success' : 'warning'}
              />
            )}
          </Stack>
          <TextField
            fullWidth
            label="Solution / Resolution"
            value={solutionText}
            onChange={(e) => setSolutionText(e.target.value)}
            multiline
            minRows={4}
            placeholder="Describe the solution provided to the customer..."
          />
          <FormControl fullWidth margin="dense" size="small">
            <InputLabel shrink>Quality follow-up</InputLabel>
            <Select
              notched
              label="Quality follow-up"
              value={openCapaAfterResolve ? 'capa' : 'none'}
              onChange={(e) => setOpenCapaAfterResolve(e.target.value === 'capa')}
            >
              <MenuItem value="none">No CAPA needed</MenuItem>
              <MenuItem value="capa">Open CAPA after resolve</MenuItem>
            </Select>
          </FormControl>
        </DialogContent>
        <DialogActions>
          <Button onClick={() => { setResolveDialog({ open: false, ticket: null }); setAiConfidence(null); }}>Cancel</Button>
          <Button onClick={() => handleResolveTicket('resolved')} variant="contained" color="success">
            Mark Resolved
          </Button>
          <Button onClick={() => handleResolveTicket('closed')} variant="outlined">
            Close
          </Button>
        </DialogActions>
      </Dialog>

      <Dialog open={capaDialog.open} onClose={() => setCapaDialog({ open: false, ticket: null })} maxWidth="sm" fullWidth>
        <DialogTitle>
          {capaDialog.ticket ? `CAPA for ticket — ${capaDialog.ticket.subject}` : 'New CAPA record'}
        </DialogTitle>
        <DialogContent>
          <TextField
            fullWidth
            margin="dense"
            label="Title"
            value={capaForm.title}
            onChange={(e) => setCapaForm((prev) => ({ ...prev, title: e.target.value }))}
            required
          />
          <TextField
            fullWidth
            margin="dense"
            label="Description / nonconformance"
            value={capaForm.description}
            onChange={(e) => setCapaForm((prev) => ({ ...prev, description: e.target.value }))}
            multiline
            minRows={3}
            required
          />
          <FormControl fullWidth margin="dense" size="small">
            <InputLabel>Severity</InputLabel>
            <Select
              value={capaForm.severity}
              label="Severity"
              onChange={(e) => setCapaForm((prev) => ({ ...prev, severity: e.target.value }))}
            >
              <MenuItem value="minor">Minor</MenuItem>
              <MenuItem value="major">Major</MenuItem>
              <MenuItem value="critical">Critical</MenuItem>
            </Select>
          </FormControl>
        </DialogContent>
        <DialogActions>
          <Button onClick={() => setCapaDialog({ open: false, ticket: null })}>Cancel</Button>
          <Button variant="contained" onClick={handleCreateCapa} disabled={creatingCapa}>
            {creatingCapa ? 'Creating…' : 'Create CAPA'}
          </Button>
        </DialogActions>
      </Dialog>

      <Dialog open={privacyDialog.open} onClose={() => setPrivacyDialog({ open: false, request: null })} maxWidth="sm" fullWidth>
        <DialogTitle>Privacy Request — {privacyDialog.request?.type}</DialogTitle>
        <DialogContent>
          <Typography variant="body2" sx={{ mb: 2 }}>{privacyDialog.request?.description}</Typography>
          <TextField
            fullWidth
            label="Response / Solution"
            value={privacyResponse}
            onChange={(e) => setPrivacyResponse(e.target.value)}
            multiline
            minRows={4}
          />
        </DialogContent>
        <DialogActions>
          <Button onClick={() => setPrivacyDialog({ open: false, request: null })}>Cancel</Button>
          <Button onClick={() => handlePrivacyUpdate('in_progress')}>In Progress</Button>
          <Button onClick={() => handlePrivacyUpdate('completed')} variant="contained" color="success">Complete</Button>
          <Button onClick={() => handlePrivacyUpdate('rejected')} color="error">Reject</Button>
        </DialogActions>
      </Dialog>
    </SupportPortalLayout>
  );
};

export default SupportDashboard;
